-- Insert Quiz Questions for Lesson: Generate a QR Code

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 22 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 22 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm22-generate-qr-code' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m22-generate-qr-code not found in module 22';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a QR code do on its own?', 
    '["It sends an email to the scanner automatically","It opens a destination URL; it does not collect data or establish consent","It automatically collects contact details from anyone who scans it","It books an appointment in the speaker''s calendar"]'::jsonb,
    'It opens a destination URL; it does not collect data or establish consent',
    'A QR code only opens a URL. It does not collect personal details or establish consent until the visitor submits a form. Do not confuse scans with leads.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why are dynamic QR codes better than static ones?', 
    '["They are required by law","They look more professional","They scan faster","You can change the destination later without generating a new code"]'::jsonb,
    'You can change the destination later without generating a new code',
    'Dynamic QR codes let you change the destination URL later. If you update your funnel or run the same talk at multiple events, you can adjust the destination without redesigning your slide.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How should you test the QR code?', 
    '["Scan it once from your desk","Only test on the newest iPhone","Testing is not necessary for HighLevel QR codes","Test with multiple devices and from a distance like the back of a room"]'::jsonb,
    'Test with multiple devices and from a distance like the back of a room',
    'Test with multiple devices and from a realistic distance. A QR that works when held close to the screen may fail when projected at the back of a large room.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

