-- Insert Quiz Questions for Lesson: Make the QR Slide and Spoken Invitation

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 22 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 22 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm22-make-qr-slide-spoken-invitation' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m22-make-qr-slide-spoken-invitation not found in module 22';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you show the QR slide during your talk?', 
    '["Continuously throughout the entire presentation","In the first five minutes to capture attention","Only after everyone has applauded","While discussing the next useful step, and again at Q&A or the end"]'::jsonb,
    'While discussing the next useful step, and again at Q&A or the end',
    'Show the QR while discussing the next useful step, and again at Q&A or the end. The audience needs to trust your content before they want your resource. Too early feels pushy; too late misses engaged attendees.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How long should the spoken invitation take?', 
    '["At least two minutes to explain all benefits","It depends on the audience size","As long as needed to cover every feature","Under 20 seconds"]'::jsonb,
    'Under 20 seconds',
    'Practice until you can deliver the invitation in under 20 seconds. Brevity respects the audience''s time and prevents the invitation from feeling like a sales pitch.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should be the largest element on the QR slide?', 
    '["The speaker''s logo and branding","The QR code itself","Testimonials from previous attendees","A detailed description of the resource"]'::jsonb,
    'The QR code itself',
    'The QR code should be the largest element. It must be scannable from the back of the room. Branding and descriptions are secondary to the code''s visibility and function.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

