-- Insert Quiz Questions for Lesson: Build the Follow-Up Workflow

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 22 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 22 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm22-build-follow-up-workflow' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m22-build-follow-up-workflow not found in module 22';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What trigger should start the resource delivery workflow?', 
    '["QR Code Scanned","Appointment Booked","Form Submitted, filtered to the specific event form","Contact Created"]'::jsonb,
    'Form Submitted, filtered to the specific event form',
    'Use Form Submitted filtered to the specific event form. A QR scan without a form submission does not fire this trigger. Only form submissions indicate genuine interest.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you avoid duplicate email delivery from both Form Autoresponder and Workflow?', 
    '["It costs more to send two emails","HighLevel does not allow both to be active","Receiving the same email twice looks unprofessional and annoys contacts","Duplicate emails are required for deliverability"]'::jsonb,
    'Receiving the same email twice looks unprofessional and annoys contacts',
    'Duplicate delivery looks unprofessional and annoys contacts. Choose one method: either the Form Autoresponder or the Workflow, not both.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should happen when a contact replies to a workflow email?', 
    '["Continue sending automated messages as planned","Automatically book an appointment for them","Stop or branch the workflow to allow human response","Send them a discount code immediately"]'::jsonb,
    'Stop or branch the workflow to allow human response',
    'A reply indicates engagement that deserves a human response. Configure the workflow to stop or branch on reply so you can respond personally rather than sending more automated messages.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

