-- Insert Quiz Questions for Lesson: Add a Booking Calendar

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 22 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 22 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm22-add-booking-calendar' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m22-add-booking-calendar not found in module 22';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How long should the booking calendar appointment be?', 
    '["As short as possible — 5 minutes is ideal","It depends on the speaker''s usual rate","15 or 20 minutes","At least one hour to cover everything"]'::jsonb,
    '15 or 20 minutes',
    'A 15- or 20-minute calendar works best. It is short enough to feel low-commitment but long enough to be genuinely useful. Longer durations create resistance; shorter durations feel rushed.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
