-- Insert Quiz Questions for Lesson: Rehearse, Launch, and Measure

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 22 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 22 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm22-rehearse-launch-measure' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m22-rehearse-launch-measure not found in module 22';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the first step in the dry run?', 
    '["Project the QR slide and verify it is scannable from a realistic distance","Send test emails to your entire contact list","Publish the funnel to social media","Book a real appointment with a colleague"]'::jsonb,
    'Project the QR slide and verify it is scannable from a realistic distance',
    'Start by projecting the QR slide and verifying it is visible and scannable. If the QR does not work in real venue conditions, the rest of the system is irrelevant.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which metric shows how well your nurture sequence converts interest to conversation?', 
    '["Emails delivered divided by QR scans","QR scans divided by audience size","Clients gained divided by audience size","Appointments booked divided by form submissions"]'::jsonb,
    'Appointments booked divided by form submissions',
    'Appointments booked ÷ form submissions shows your conversion from lead to conversation. This reveals how well your nurture sequence and offer resonate with interested people.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Do QR scans automatically equal individual leads?', 
    '["Yes, every scan creates a new lead record","No, scans indicate interest but do not create leads until the form is submitted","Only if the scanner has an account","Yes, but only on iPhones"]'::jsonb,
    'No, scans indicate interest but do not create leads until the form is submitted',
    'QR scans indicate interest but do not automatically create leads. The same person may scan multiple times. Only form submissions create contact records and trigger workflows.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
